  always @(*) begin
    case (state)
     2'b00: nextstate = in ? 2'b01 : 2'b00;
     2'b01: nextstate = in ? 2'b10 : 2'b00;
     2'b10: nextstate = in ? 2'b01 : 2'b00;
     2'b11: nextstate = in ? 2'b10 : 2'b00;
     default: nextstate = 2'b00;
    endcase
  end
  always @(posedge clk) begin
    if (areset) state <= 2'b00;
    else state <= nextstate;
  end
  assign out = (state == 2'b01);
endmodule

